using System.Linq;
using UnityEngine;
using UnityEditor;
using TMPro;
using LWS.TruckSports;
namespace LWS.TruckPedestrianPlowing.Editor {
 public static class PlowBadgesAuthoring {
  public static TMP_Text Label(string name,string text,Vector3 position,float size,Color color){var g=new GameObject(name,typeof(RectTransform));g.transform.position=position;g.layer=2;var label=g.AddComponent<TextMeshPro>();Configure(label);label.text=text;label.color=color;return label;}
  static void Configure(TMP_Text label){var theme=Resources.Load<SportsBroadcastTheme>("SportsBroadcastTheme");label.font=theme.bodyFont;string path=PlowAuthoring.Root+"/Materials/Depth tested role text.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(mat==null){mat=new Material(theme.bodyFont.material);mat.name="Depth tested role text";mat.SetFloat("_CullMode",2);mat.SetFloat("_ZTestMode",4);mat.SetFloat("_OutlineWidth",.12f);mat.SetColor("_OutlineColor",new Color(.02f,.025f,.035f));AssetDatabase.CreateAsset(mat,path);}label.fontSharedMaterial=mat;label.fontSize=2.5f;label.alignment=TextAlignmentOptions.Center;label.textWrappingMode=TextWrappingModes.NoWrap;label.rectTransform.sizeDelta=new Vector2(1.1f,.7f);label.raycastTarget=false;label.GetComponent<Renderer>().shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;}
  static TMP_Text Convert(PlowPedestrian ped,string name){var old=ped.GetComponentsInChildren<Transform>(true).First(t=>t.name==name);var current=old.GetComponent<TMP_Text>();if(current!=null){Configure(current);return current;}var parent=old.parent;var position=old.localPosition;var rotation=old.localRotation;var scale=old.localScale;UnityEngine.Object.DestroyImmediate(old.gameObject);var label=Label(name,"+10",Vector3.zero,.025f,Color.white);label.transform.SetParent(parent,false);label.transform.SetLocalPositionAndRotation(position,rotation);label.transform.localScale=scale;return label;}
  public static void Install(){foreach(var id in AssetDatabase.FindAssets("t:Prefab",new[]{PlowAuthoring.Root+"/Prefabs"})){string path=AssetDatabase.GUIDToAssetPath(id);var root=PrefabUtility.LoadPrefabContents(path);try{var ped=root.GetComponent<PlowPedestrian>();if(ped==null)continue;CostumeNose(ped);ped.frontBadge=Convert(ped,"Front role badge");ped.backBadge=Convert(ped,"Rear role badge");ped.beacon=Convert(ped,"Overhead scoring symbol");ped.frontBadge.transform.position=new Vector3(0,.72f,.29f);ped.backBadge.transform.position=new Vector3(0,.72f,-.29f);ped.frontBadge.transform.rotation=Quaternion.Euler(0,180,0);ped.backBadge.transform.rotation=Quaternion.identity;if(ped.goldSymbols==null){ped.goldSymbols=Symbols(ped,"Gold star symbols",true);ped.stopSymbols=Symbols(ped,"Stop cross symbols",false);}foreach(var r in ped.goldSymbols.GetComponentsInChildren<Renderer>(true))r.sharedMaterial=SymbolMaterial(true);foreach(var r in ped.stopSymbols.GetComponentsInChildren<Renderer>(true))r.sharedMaterial=SymbolMaterial(false);PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}AssetDatabase.SaveAssets();}
  static Material SymbolMaterial(bool star){string path=PlowAuthoring.Root+"/Materials/"+(star?"Role star ink":"Role stop ivory")+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(mat==null){mat=new Material(Shader.Find("Universal Render Pipeline/Unlit"));mat.SetColor("_BaseColor",star?new Color(.025f,.03f,.045f):Color.white);AssetDatabase.CreateAsset(mat,path);}return mat;}
  public static void CostumeNose(PlowPedestrian ped){
   var head=ped.GetComponentsInChildren<Transform>(true).First(t=>t.name=="Bip01 Head");
   var existing=head.Find("Standard cartoon costume nose");
   var parts=head.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.GetComponent<TMP_Text>()==null&&r.name!="Standard cartoon costume nose").ToArray();
   var face=parts.FirstOrDefault(r=>r.name=="Head");var eyes=parts.Where(r=>r.name.EndsWith("eye",System.StringComparison.OrdinalIgnoreCase)).ToArray();
   Vector3 position=head.position+new Vector3(0,.05f,.3f);if(eyes.Length>0){position=Vector3.zero;foreach(var eye in eyes)position+=eye.bounds.center;position/=eyes.Length;position+=new Vector3(0,-.035f,.12f);}else if(face!=null)position=new Vector3(face.bounds.center.x,face.bounds.center.y,face.bounds.max.z+.12f);
   var g=existing!=null?existing.gameObject:GameObject.CreatePrimitive(PrimitiveType.Sphere);g.name="Standard cartoon costume nose";var collider=g.GetComponent<Collider>();if(collider!=null)UnityEngine.Object.DestroyImmediate(collider);g.layer=2;g.transform.SetParent(null,true);g.transform.SetPositionAndRotation(position,Quaternion.identity);g.transform.localScale=new Vector3(.3f,.3f,.5f);g.transform.SetParent(head,true);
   string path=PlowAuthoring.Root+"/Materials/Standard costume blue.mat";var material=AssetDatabase.LoadAssetAtPath<Material>(path);if(material==null){material=new Material(Shader.Find("Universal Render Pipeline/Lit"));material.SetColor("_BaseColor",new Color(.04f,.55f,1));material.SetFloat("_Smoothness",.48f);AssetDatabase.CreateAsset(material,path);}ped.costumeNose=g.GetComponent<Renderer>();ped.costumeNose.sharedMaterial=material;ped.costumeNose.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;g.SetActive(false);
  }
  static GameObject Symbols(PlowPedestrian ped,string name,bool star){var g=new GameObject(name);g.transform.SetParent(ped.frontBadge.transform.parent,true);g.transform.position=Vector3.zero;foreach(float side in new[]{-1f,1f}){var symbol=new GameObject(star?"Five-point star":"STOP cross");symbol.transform.SetParent(g.transform,true);symbol.transform.position=new Vector3(0,1.02f,side*.31f);symbol.transform.rotation=Quaternion.Euler(0,side<0?180:0,0);var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(PlowAuthoring.Root+"/Models/"+(star?"Role star":"Role cross")+".asset");if(mesh==null){mesh=new Mesh();if(star){var v=new Vector3[11];for(int i=0;i<10;i++){float a=i*Mathf.PI/5;v[i+1]=new Vector3(Mathf.Sin(a),Mathf.Cos(a),0)*(i%2==0?.15f:.065f);}var t=new int[60];for(int i=0;i<10;i++){int j=(i+1)%10+1;t[i*6]=0;t[i*6+1]=i+1;t[i*6+2]=j;t[i*6+3]=0;t[i*6+4]=j;t[i*6+5]=i+1;}mesh.vertices=v;mesh.triangles=t;}else{mesh.vertices=new[]{new Vector3(-.13f,-.09f),new Vector3(-.09f,-.13f),new Vector3(.13f,.09f),new Vector3(.09f,.13f),new Vector3(-.13f,.09f),new Vector3(-.09f,.13f),new Vector3(.13f,-.09f),new Vector3(.09f,-.13f)};mesh.triangles=new[]{0,1,2,0,2,3,2,1,0,3,2,0,4,5,6,4,6,7,6,5,4,7,6,4};}mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,PlowAuthoring.Root+"/Models/"+(star?"Role star":"Role cross")+".asset");}symbol.AddComponent<MeshFilter>().sharedMesh=mesh;symbol.AddComponent<MeshRenderer>().sharedMaterial=SymbolMaterial(star);symbol.layer=2;}g.SetActive(false);return g;}
 }
}
